    {"surface": "船積指図書", "reading": "ふなづみさしずしょ", "vi_short": "chỉ dẫn giao hàng cho hãng tàu (Shipping Order - S/O)", "vi_explanation": "Chứng từ do chủ hàng hoặc người giao nhận gửi cho thuyền trưởng hướng dẫn bốc hàng lên tàu theo đúng sơ đồ xếp hàng.", "en_preferred": "Shipping Order (S/O)", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:documents", "synonyms": ['S/O'], "antonyms": [], "related_terms": ['船積依頼書', 'メイツレシート']},
