    {"surface": "クリーンB/L", "reading": "くりーんびーえる", "vi_short": "vận đơn hoàn hảo / vận đơn sạch (Clean B/L)", "vi_explanation": "Vận đơn không có bất kỳ dòng ghi chú nào của thuyền phó về tình trạng bao bì hay hàng hóa bị hư hỏng, rách nát.", "en_preferred": "Clean Bill of Lading", "tier": "PRO-A1", "priority": 96, "source_reference": "jetro_trade_corpus:documents", "synonyms": ['無故障B/L'], "antonyms": ['故障付B/L'], "related_terms": ['メイツレシート', '信用状']},
    {"surface": "故障付B/L", "reading": "こしょうつきびーえる", "vi_short": "vận đơn không hoàn hảo (Foul B/L / Claused B/L)", "vi_explanation": "Vận đơn có ghi chú của hãng tàu về việc bao bì bị rách, ướt hoặc hàng bị biến dạng (thường bị ngân hàng từ chối thanh toán theo L/C).", "en_preferred": "Claused B/L / Foul B/L", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:documents", "synonyms": ['有故障B/L'], "antonyms": ['クリーンB/L'], "related_terms": ['ディスクレ', 'L/C']},
