    {"surface": "スイッチB/L", "reading": "すいっちびーえる", "vi_short": "vận đơn chuyển đổi trong thương mại ba bên (Switch B/L)", "vi_explanation": "Tập vận đơn thứ hai được hãng tàu cấp đổi để thay thế tập vận đơn gốc, nhằm che giấu danh tính nhà máy sản xuất thật khỏi người mua cuối cùng.", "en_preferred": "Switch B/L", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:documents", "synonyms": [], "antonyms": [], "related_terms": ['三国間貿易', '仲介貿易']},
