    {"surface": "輸入申告", "reading": "ゆにゅうしんこく", "vi_short": "kê khai hải quan nhập khẩu", "vi_explanation": "Thủ tục nộp hồ sơ kê khai phân loại mã hàng, số lượng và tính thuế nhập khẩu cho hàng hóa từ nước ngoài gửi tới.", "en_preferred": "Import declaration", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['輸出申告'], "related_terms": ['輸入許可', '納税申告']},
    {"surface": "輸出許可", "reading": "ゆしゅつきょか", "vi_short": "thông quan xuất khẩu thành công", "vi_explanation": "Quyết định chính thức của cơ quan hải quan cho phép bốc dỡ lô hàng xuất khẩu lên phương tiện vận tải ra nước ngoài.", "en_preferred": "Export permission / Export clearance", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['輸入許可'], "related_terms": ['輸出許可書', '通関']},
    {"surface": "輸入許可", "reading": "ゆにゅうきょか", "vi_short": "thông quan nhập khẩu hoàn tất", "vi_explanation": "Sự phê duyệt của hải quan sau khi hàng hóa đã nộp đủ các loại thuế, cho phép mang hàng ra khỏi khu vực giám sát hải quan.", "en_preferred": "Import permission / Import clearance", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['輸出許可'], "related_terms": ['輸入許可書', '国内引取']},
    {"surface": "通関手続き", "reading": "つうかんてつづき", "vi_short": "thủ tục thông quan hải quan trọn gói", "vi_explanation": "Toàn bộ chuỗi quy trình nộp tờ khai, xuất trình chứng từ, kiểm tra thực tế hàng hóa và nộp thuế quan tại cửa khẩu.", "en_preferred": "Customs clearance procedure", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['税関', '通関業者']},
    {"surface": "関税", "reading": "かんぜい", "vi_short": "thuế quan / thuế nhập khẩu", "vi_explanation": "Thuế quốc gia đánh trên hàng hóa có xuất xứ từ nước ngoài khi được nhập khẩu vào thị trường Nhật Bản.", "en_preferred": "Customs duty / Tariff", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['関税率', '課税価格', '消費税']},
    {"surface": "関税率", "reading": "かんぜいりつ", "vi_short": "thuế suất thuế nhập khẩu", "vi_explanation": "Tỷ lệ phần trăm hoặc số tiền cố định áp dụng cho từng nhóm mã hàng hóa theo quy định của biểu thuế hải quan.", "en_preferred": "Tariff rate / Customs duty rate", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['実行関税率表', '協定税率']},
    {"surface": "協定税率", "reading": "きょうていぜいりつ", "vi_short": "thuế suất theo hiệp định WTO / EPA", "vi_explanation": "Thuế suất ưu đãi đàm phán quốc tế cam kết không được vượt quá, được ưu tiên áp dụng thay cho thuế suất cơ bản nội địa.", "en_preferred": "Concession tax rate / WTO bound rate", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['基本税率'], "related_terms": ['EPA税率', '特恵税率']},
    {"surface": "特恵税率", "reading": "とっけいぜいりつ", "vi_short": "thuế suất ưu đãi đặc biệt cho các nước đang phát triển (GSP)", "vi_explanation": "Biểu thuế giảm nhẹ đặc biệt mà chính phủ Nhật Bản đơn phương dành riêng cho hàng hóa nhập khẩu từ các nước đang phát triển.", "en_preferred": "Generalized System of Preferences (GSP) rate", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['GSP'], "antonyms": [], "related_terms": ['基本税率', '原産地証明書']},
    {"surface": "暫定税率", "reading": "ざんていぜいりつ", "vi_short": "thuế suất áp dụng tạm thời trong năm tài khóa", "vi_explanation": "Mức thuế quan do quốc hội ban hành áp dụng tạm thời cho một số mặt hàng trong một thời hạn nhất định thay cho thuế suất cơ bản.", "en_preferred": "Temporary duty rate", "tier": "PRO-A2", "priority": 90, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['基本税率'], "related_terms": ['実行関税率表']},
    {"surface": "実行関税率表", "reading": "じっこうかんぜいりつひょう", "vi_short": "biểu thuế quan xuất nhập khẩu hiện hành của Nhật Bản", "vi_explanation": "Bảng tra cứu chính thức của Hải quan Nhật Bản kết hợp giữa mã số HS 9 chữ số và các mức thuế suất áp dụng thực tế.", "en_preferred": "Customs Tariff Schedule of Japan", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['HSコード', '関税率']},
    {"surface": "HSコード", "reading": "えいちえすこーど", "vi_short": "mã số phân loại hàng hóa quốc tế (HS Code)", "vi_explanation": "Hệ thống mã số tiêu chuẩn gồm 6 chữ số thống nhất toàn cầu do Tổ chức Hải quan Thế giới (WCO) ban hành để định danh hàng hóa.", "en_preferred": "Harmonized System Code (HS Code)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['関税分類番号'], "antonyms": [], "related_terms": ['実行関税率表', '統計品目番号']},
    {"surface": "統計品目番号", "reading": "とうけいひんもくばんごう", "vi_short": "mã thống kê hàng hóa chi tiết 9 chữ số tại Nhật", "vi_explanation": "Mã số gồm 9 chữ số (6 số HS quốc tế + 3 số chi tiết của Nhật Bản) dùng để khai báo chính xác thuế suất và thống kê ngoại thương.", "en_preferred": "Statistical code (9-digit national code)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['HSコード', '税関']},
    {"surface": "税関検査", "reading": "ぜいかんけんさ", "vi_short": "kiểm tra thực tế hàng hóa tại hải quan", "vi_explanation": "Việc cán bộ hải quan tiến hành rà soát, cân đo hoặc mở kiện hàng để đối chiếu xem hàng hóa có đúng như tờ khai đã nộp hay không.", "en_preferred": "Customs examination / Customs inspection", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['抜取検査', '大型X線検査']},
    {"surface": "抜取検査", "reading": "ぬきとりけんさ", "vi_short": "kiểm tra mẫu ngẫu nhiên vài kiện hàng", "vi_explanation": "Hình thức kiểm tra chọn ngẫu nhiên một số bao hoặc thùng hàng trong cả lô container để mở ra kiểm tra tính xác thực.", "en_preferred": "Sample inspection / Spot check", "tier": "PRO-A1", "priority": 96, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['全量検査'], "related_terms": ['税関検査', '貨物検査']},
    {"surface": "全量検査", "reading": "ぜんりょうけんさ", "vi_short": "kiểm tra toàn bộ 100% lô hàng", "vi_explanation": "Hình thức kiểm tra mở bung toàn bộ hàng hóa trong container do nghi ngờ gian lận thương mại hoặc chứa chất cấm buôn lậu.", "en_preferred": "Full physical inspection (100% inspection)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['抜取検査'], "related_terms": ['税関検査', '密輸']},
    {"surface": "大型X線検査", "reading": "おおがたえっくすせんけんさ", "vi_short": "soi chiếu nguyên container qua máy quét X-quang", "vi_explanation": "Phương pháp kiểm tra hiện đại cho xe đầu kéo chở cả thùng container chạy qua cổng quét tia X mà không cần phải dỡ hàng.", "en_preferred": "Large-scale X-ray inspection", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['コンテナ検査', '税関']},
    {"surface": "課税価格", "reading": "かぜいかかく", "vi_short": "trị giá tính thuế hải quan (CIF value)", "vi_explanation": "Trị giá của lô hàng tại thời điểm đến cảng Nhật Bản (thường tính bằng giá CIF: tiền hàng + bảo hiểm + cước biển quy đổi sang Yên).", "en_preferred": "Customs value / Dutiable value", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['関税評価', 'CIF', '関税']},
    {"surface": "関税評価", "reading": "かんぜいひょうか", "vi_short": "thẩm định trị giá tính thuế hải quan", "vi_explanation": "Quy trình xác định trị giá hợp lý của hàng hóa nhập khẩu theo các hiệp định định giá của WTO khi có nghi ngờ khai báo giá thấp.", "en_preferred": "Customs valuation", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['課税価格', '移転価格']},
    {"surface": "従価税", "reading": "じゅうかぜい", "vi_short": "thuế tính theo tỷ lệ phần trăm trị giá hàng", "vi_explanation": "Phương pháp tính thuế quan bằng cách nhân tỷ lệ phần trăm (ví dụ 5% hoặc 10%) với tổng trị giá tính thuế CIF của hàng hóa.", "en_preferred": "Ad valorem duty", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['従量税'], "related_terms": ['課税価格', '関税率']},
    {"surface": "従量税", "reading": "じゅうりょうぜい", "vi_short": "thuế tính theo khối lượng hoặc số lượng vật lý", "vi_explanation": "Phương pháp tính thuế ấn định số tiền cụ thể trên một đơn vị đo lường (như 50 yên trên mỗi kg hoặc 100 yên trên mỗi lít rượu).", "en_preferred": "Specific duty", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['従価税'], "related_terms": ['重量', '関税']},
    {"surface": "混合税", "reading": "こんごうぜい", "vi_short": "thuế kết hợp cả trị giá và số lượng", "vi_explanation": "Loại thuế quan áp dụng đồng thời cả thuế theo tỷ lệ phần trăm và thuế theo đơn vị số lượng để bảo hộ chặt chẽ sản xuất nội địa.", "en_preferred": "Compound duty / Mixed tariff", "tier": "PRO-A3", "priority": 89, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['従価税', '従量税']},
    {"surface": "差額関税", "reading": "さがくかんぜい", "vi_short": "thuế chênh lệch giá bảo hộ thịt lợn", "vi_explanation": "Cơ chế thuế nhập khẩu riêng biệt áp dụng cho thịt lợn: nếu giá nhập khẩu thấp hơn giá sàn tiêu chuẩn, người nhập phải nộp thuế bù bằng đúng khoảng chênh lệch.", "en_preferred": "Differential tariff system", "tier": "PRO-A3", "priority": 88, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['豚肉関税', '関税政策']},
    {"surface": "関税割当制度", "reading": "かんぜいわりあてせいど", "vi_short": "chế độ hạn ngạch thuế quan (Tariff Quota - TRQ)", "vi_explanation": "Chế độ cho phép nhập khẩu một khối lượng hàng nhất định với thuế suất cực thấp; nếu nhập khẩu vượt quá số lượng hạn ngạch thì phải chịu thuế suất rất cao.", "en_preferred": "Tariff Quota System (TRQ)", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['TRQ'], "antonyms": [], "related_terms": ['枠内税率', '枠外税率']},
    {"surface": "不当廉売関税", "reading": "ふとうれんばいかんぜい", "vi_short": "thuế chống bán phá giá (Anti-dumping Duty)", "vi_explanation": "Thuế bổ sung đánh phạt lên hàng hóa nước ngoài bán phá giá thấp hơn giá thành sản xuất làm tổn hại ngành công nghiệp trong nước.", "en_preferred": "Anti-dumping duty (AD)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['アンチダンピング税'], "antonyms": [], "related_terms": ['相殺関税', 'WTO']},
    {"surface": "相殺関税", "reading": "そうさいかんぜい", "vi_short": "thuế chống trợ cấp (Countervailing Duty)", "vi_explanation": "Thuế quan đánh lên hàng nhập khẩu được chính phủ nước xuất khẩu trợ cấp tài chính trực tiếp làm méo mó cạnh tranh công bằng.", "en_preferred": "Countervailing duty (CVD)", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['CVD'], "antonyms": [], "related_terms": ['不当廉売関税', '補助金']},
    {"surface": "緊急関税", "reading": "きんきゅうかんぜい", "vi_short": "biện pháp tự vệ thương mại khẩn cấp (Safeguard)", "vi_explanation": "Biện pháp tăng vọt thuế quan khẩn cấp nhằm ngăn chặn sự gia tăng đột biến hàng nhập khẩu đang đe dọa phá hủy ngành sản xuất nội địa.", "en_preferred": "Safeguard duty", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['セーフガード'], "antonyms": [], "related_terms": ['関税法', '輸入制限']},
    {"surface": "保税地域", "reading": "ほぜいちいき", "vi_short": "khu vực bảo thuế hải quan", "vi_explanation": "Khu vực kho bãi hoặc bến cảng được Nhà nước chỉ định, cho phép lưu giữ, gia công hoặc trưng bày hàng hóa nước ngoài mà chưa cần nộp thuế quan.", "en_preferred": "Bonded area", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['保税蔵置場', '保税運送', '外国貨物']},
    {"surface": "指定保税地域", "reading": "していほぜいちいき", "vi_short": "khu vực bảo thuế công cộng do nhà nước chỉ định", "vi_explanation": "Khu vực đất công cộng tại bến cảng hoặc sân bay do Bộ Tài chính chỉ định để bốc dỡ và lưu giữ hàng hóa tạm thời.", "en_preferred": "Designated bonded area", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['保税地域', '保税蔵置場']},
    {"surface": "保税蔵置場", "reading": "ほぜいぞうちじょう", "vi_short": "kho bảo thuế tư nhân được cấp phép", "vi_explanation": "Nhà kho do doanh nghiệp logistics tư nhân đầu tư và được Hải quan cấp phép để chứa hàng hóa nước ngoài trong thời hạn tối đa 2 năm.", "en_preferred": "Bonded warehouse", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['保税倉庫'], "antonyms": [], "related_terms": ['保税地域', '蔵入れ']},
    {"surface": "保税工場", "reading": "ほぜいこうじょう", "vi_short": "nhà máy gia công sản xuất bảo thuế", "vi_explanation": "Khu nhà xưởng sản xuất cho phép nhập khẩu nguyên vật liệu nước ngoài về gia công thành sản phẩm rồi xuất khẩu mà không phải nộp bất kỳ khoản thuế nào.", "en_preferred": "Bonded manufacturing warehouse / Bonded factory", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['保税地域', '加工貿易']},
    {"surface": "保税展示場", "reading": "ほぜいてんじじょう", "vi_short": "trung tâm triển lãm quốc tế bảo thuế", "vi_explanation": "Địa điểm tổ chức hội chợ quốc tế cho phép đem các mẫu máy móc từ nước ngoài vào trưng bày triển lãm mà không cần làm thủ tục nhập khẩu nộp thuế.", "en_preferred": "Bonded exhibition site", "tier": "PRO-A2", "priority": 90, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['東京ビッグサイト', '見本市']},
    {"surface": "総合保税地域", "reading": "そうごうほぜいちいき", "vi_short": "khu kinh tế bảo thuế tích hợp đa chức năng", "vi_explanation": "Khu phức hợp công nghiệp quy mô lớn kết hợp toàn bộ các chức năng lưu kho, gia công, chế tạo và trưng bày hàng hóa.", "en_preferred": "Integrated bonded area", "tier": "PRO-A2", "priority": 90, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['保税地域']},
    {"surface": "保税運送", "reading": "ほぜいうんそう", "vi_short": "vận chuyển hàng hóa bảo thuế giữa các kho bãi", "vi_explanation": "Việc vận chuyển hàng nước ngoài chưa nộp thuế từ cảng biển vào sâu trong nội địa dưới sự giám sát nghiêm ngặt của hải quan.", "en_preferred": "Bonded transportation", "tier": "PRO-A1", "priority": 96, "source_reference": "jetro_trade_corpus:customs", "synonyms": ['OLT'], "antonyms": [], "related_terms": ['保税地域', '運送申告']},
    {"surface": "外国貨物", "reading": "がいこくかもつ", "vi_short": "hàng hóa nước ngoài chưa thông quan", "vi_explanation": "Hàng hóa từ nước ngoài đưa đến Nhật Bản nhưng chưa được cơ quan Hải quan cấp phép nhập khẩu chính thức (chưa nộp thuế).", "en_preferred": "Foreign cargo", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['内国貨物'], "related_terms": ['保税地域', '輸入許可']},
    {"surface": "内国貨物", "reading": "ないこくかもつ", "vi_short": "hàng hóa nội địa / hàng đã thông quan hợp pháp", "vi_explanation": "Hàng hóa sản xuất tại Nhật Bản hoặc hàng nước ngoài đã hoàn tất mọi thủ tục hải quan nộp thuế và được cấp giấy phép nhập khẩu.", "en_preferred": "Domestic cargo", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['外国貨物'], "related_terms": ['輸入許可', '流通']},
    {"surface": "蔵入れ", "reading": "くらいれ", "vi_short": "thủ tục đưa hàng vào lưu giữ trong kho bảo thuế", "vi_explanation": "Hành động khai báo hải quan xin đưa lô hàng nước ngoài vào lưu kho tại kho bảo thuế để hoãn thời điểm nộp thuế nhập khẩu.", "en_preferred": "Placing cargo into bonded warehouse", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['蔵出し'], "related_terms": ['保税蔵置場', '倉荷証券']},
    {"surface": "蔵出し", "reading": "くらだし", "vi_short": "thủ tục xuất hàng ra khỏi kho bảo thuế để nhập khẩu", "vi_explanation": "Thủ tục nộp tờ khai nhập khẩu và đóng thuế để đưa hàng hóa từ kho bảo thuế ra tiêu thụ tại thị trường trong nước.", "en_preferred": "Withdrawal of cargo from bonded warehouse", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": ['蔵入れ'], "related_terms": ['輸入申告', '内国貨物']},
    {"surface": "他法令確認", "reading": "たほうれいかくにん", "vi_short": "kiểm tra điều kiện theo các đạo luật chuyên ngành khác", "vi_explanation": "Yêu cầu hải quan sẽ không cấp phép thông quan nếu doanh nghiệp chưa hoàn thành kiểm dịch hoặc chứng nhận hợp chuẩn theo các bộ luật khác.", "en_preferred": "Confirmation of other laws and regulations", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['食品衛生法', '薬機法', '植物防疫法']},
    {"surface": "食品衛生法", "reading": "しょくひんえいせいほう", "vi_short": "Luật Vệ sinh An toàn Thực phẩm Nhật Bản", "vi_explanation": "Đạo luật bắt buộc yêu cầu nộp hồ sơ xin kiểm nghiệm hóa sinh đối với thực phẩm, bát đĩa, đồ dùng nhà bếp và đồ chơi trẻ em nhập khẩu.", "en_preferred": "Food Sanitation Act", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['食品等輸入届出書', '検疫所']},
    {"surface": "植物防疫法", "reading": "しょくぶつぼうえきほう", "vi_short": "Luật Kiểm dịch Bảo vệ Thực vật", "vi_explanation": "Đạo luật ngăn ngừa sâu bọ, vi khuẩn gây hại từ nước ngoài xâm nhập qua đường nhập khẩu rau củ quả, hoa tươi hoặc cây giống.", "en_preferred": "Plant Protection Act", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['植物検疫証明書', '植物防疫所']},
    {"surface": "家畜伝染病予防法", "reading": "かちくでんせんびょうよぼうほう", "vi_short": "Luật Phòng chống Bệnh truyền nhiễm Gia súc (Kiểm dịch động vật)", "vi_explanation": "Quy định kiểm soát thú y khắt khe đối với thịt gia súc, gia cầm, trứng và sản phẩm từ sữa để ngăn ngừa dịch tả lợn châu Phi và cúm gia cầm.", "en_preferred": "Act on the Prevention of Infectious Diseases in Livestock", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:customs", "synonyms": [], "antonyms": [], "related_terms": ['動物検疫所', '衛生証明書']},
    {"surface": "信用状", "reading": "しんようじょう", "vi_short": "thư tín dụng thanh toán quốc tế (Letter of Credit - L/C)", "vi_explanation": "Cam kết trả tiền bằng văn bản không hủy ngang do ngân hàng mở thay mặt người mua phát hành, bảo đảm trả tiền cho người bán khi nhận đủ chứng từ hợp lệ.", "en_preferred": "Letter of Credit (L/C)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['L/C'], "antonyms": [], "related_terms": ['取消不能信用状', 'ディスクレ', '荷為替手形']},
    {"surface": "取消不能信用状", "reading": "とりけしふのうしんようじょう", "vi_short": "thư tín dụng không thể đơn phương hủy ngang (Irrevocable L/C)", "vi_explanation": "Loại L/C tiêu chuẩn hiện đại mà ngân hàng phát hành tuyệt đối không được tự ý sửa đổi hoặc hủy bỏ nếu không có sự đồng ý của tất cả các bên.", "en_preferred": "Irrevocable Letter of Credit", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['信用状', 'UCP600']},
    {"surface": "確認信用状", "reading": "かくにんしんようじょう", "vi_short": "thư tín dụng được bảo lãnh xác nhận (Confirmed L/C)", "vi_explanation": "L/C có thêm cam kết trả tiền độc lập của một ngân hàng quốc tế uy tín thứ hai để phòng ngừa rủi ro ngân hàng phát hành bị vỡ nợ.", "en_preferred": "Confirmed Letter of Credit", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['確認銀行', 'カントリーリスク']},
    {"surface": "譲渡可能信用状", "reading": "じょうとかのうしんようじょう", "vi_short": "thư tín dụng có thể chuyển nhượng (Transferable L/C)", "vi_explanation": "Loại L/C cho phép người thụ hưởng ban đầu (nhà thương mại trung gian) được chuyển nhượng quyền nhận tiền cho nhà sản xuất thực tế.", "en_preferred": "Transferable Letter of Credit", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['仲介貿易', '第2受益者']},
    {"surface": "回転信用状", "reading": "かいてんしんようじょう", "vi_short": "thư tín dụng tuần hoàn tái sinh số tiền (Revolving L/C)", "vi_explanation": "L/C tự động phục hồi lại nguyên số tiền giá trị thanh toán ban đầu sau khi mỗi đợt giao hàng được thanh toán xong mà không cần mở thư mới.", "en_preferred": "Revolving Letter of Credit", "tier": "PRO-A2", "priority": 90, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['定期取引', '分割船積み']},
    {"surface": "スタンドバイL/C", "reading": "すたんどばいえるしー", "vi_short": "thư tín dụng dự phòng bảo lãnh (Standby L/C)", "vi_explanation": "Hình thức bảo lãnh ngân hàng cam kết bồi thường trả tiền cho đối tác nếu khách hàng của ngân hàng không thực hiện đúng nghĩa vụ hợp đồng.", "en_preferred": "Standby Letter of Credit", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['銀行保証', '履行保証']},
    {"surface": "信用状発行依頼書", "reading": "しんようじょうはっこういらいしょ", "vi_short": "đơn đề nghị mở thư tín dụng L/C", "vi_explanation": "Mẫu đơn người nhập khẩu nộp cho ngân hàng yêu cầu ký quỹ và phát hành thư tín dụng gửi sang cho đối tác nước ngoài.", "en_preferred": "Application for Letter of Credit", "tier": "PRO-A1", "priority": 96, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['開設銀行', '輸入者']},
    {"surface": "開設銀行", "reading": "かいせつぎんこう", "vi_short": "ngân hàng phát hành thư tín dụng (Issuing Bank)", "vi_explanation": "Ngân hàng tại quốc gia người mua đứng ra phát hành cam kết thanh toán L/C cho người xuất khẩu.", "en_preferred": "Issuing Bank / Opening Bank", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['発効銀行'], "antonyms": [], "related_terms": ['通知銀行', '信用状']},
    {"surface": "通知銀行", "reading": "つうちぎんこう", "vi_short": "ngân hàng thông báo thư tín dụng (Advising Bank)", "vi_explanation": "Ngân hàng đại lý tại quốc gia người bán tiếp nhận thông điệp SWIFT của L/C và kiểm tra tính chân thực trước khi chuyển giao cho người bán.", "en_preferred": "Advising Bank", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['開設銀行', '受益者']},
    {"surface": "買取銀行", "reading": "かいとりぎんこう", "vi_short": "ngân hàng chiết khấu thanh toán chứng từ (Negotiating Bank)", "vi_explanation": "Ngân hàng mua lại hối phiếu và bộ chứng từ xuất khẩu của người bán để giải ngân trả tiền trước cho người bán.", "en_preferred": "Negotiating Bank", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['手形買取', '荷為替']},
    {"surface": "ディスクレ", "reading": "でぃすくれ", "vi_short": "sai sót bất hợp lệ trong bộ chứng từ L/C (Discrepancy)", "vi_explanation": "Sự không trùng khớp giữa số liệu trên hóa đơn, vận đơn với các điều khoản đã ghi trong thư tín dụng L/C, khiến ngân hàng từ chối thanh toán.", "en_preferred": "Discrepancy (Discrepant documents)", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['ディスクレパンシー', '不一致'], "antonyms": [], "related_terms": ['信用状', '買取拒絶', 'アメンド']},
    {"surface": "アメンド", "reading": "あめんど", "vi_short": "tu chỉnh bổ sung nội dung thư tín dụng L/C (Amendment)", "vi_explanation": "Việc người mua và người bán thỏa thuận sửa đổi thời hạn giao hàng hoặc số tiền trên L/C thông qua thông báo tu chỉnh chính thức của ngân hàng.", "en_preferred": "Amendment of Letter of Credit", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['条件変更'], "antonyms": [], "related_terms": ['信用状', 'ディスクレ']},
    {"surface": "為替手形", "reading": "かわせてがた", "vi_short": "hối phiếu thương mại (Bill of Exchange)", "vi_explanation": "Lệnh đòi tiền vô điều kiện bằng văn bản do người bán ký phát gửi cho người mua hoặc ngân hàng yêu cầu trả một số tiền nhất định.", "en_preferred": "Bill of Exchange", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['手形'], "antonyms": [], "related_terms": ['荷為替', '満期日', '振出人']},
    {"surface": "荷為替", "reading": "にがわせ", "vi_short": "thanh toán nhờ thu kèm chứng từ hàng hóa", "vi_explanation": "Phương thức thanh toán mà người bán gửi bộ chứng từ hàng hóa kèm hối phiếu qua hệ thống ngân hàng để yêu cầu người mua trả tiền mới giao chứng từ nhận hàng.", "en_preferred": "Documentary bill / Documentary collection", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['D/P', 'D/A', '船荷証券']},
    {"surface": "手形買取", "reading": "てがたかいとり", "vi_short": "chiết khấu hối phiếu xuất khẩu", "vi_explanation": "Nghiệp vụ ngân hàng ứng tiền mặt trước cho nhà xuất khẩu bằng cách mua lại bộ hối phiếu đã xuất trình hợp lệ trước ngày đáo hạn.", "en_preferred": "Negotiation of bills / Bill discounting", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['買取銀行', '為替手形']},
    {"surface": "手形取立", "reading": "てがたとりたて", "vi_short": "nhờ thu hối phiếu qua ngân hàng", "vi_explanation": "Ngân hàng chỉ đóng vai trò trung gian thu hộ tiền từ người mua ở nước ngoài về chuyển lại cho người bán mà không chịu rủi ro tín dụng.", "en_preferred": "Collection of bills", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['取立手数料', '荷為替']},
    {"surface": "電信送金", "reading": "でんしんそうきん", "vi_short": "chuyển tiền bằng điện tín quốc tế qua mạng SWIFT", "vi_explanation": "Phương thức chuyển tiền thanh toán quốc tế trực tiếp từ tài khoản ngân hàng bên mua sang bên bán thông qua mạng lưới điện toán viễn thông SWIFT.", "en_preferred": "Telegraphic Transfer (T/T)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['T/T'], "antonyms": [], "related_terms": ['前受送金', 'SWIFTコード']},
    {"surface": "前受送金", "reading": "まえうけそうきん", "vi_short": "thanh toán chuyển tiền trả trước 100% (Advance T/T)", "vi_explanation": "Phương thức bên mua phải chuyển đủ 100% tiền thanh toán vào tài khoản của bên bán trước khi hàng hóa được sản xuất hoặc giao lên tàu.", "en_preferred": "Advance payment by T/T / Cash in advance", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": ['後日送金'], "related_terms": ['電信送金', '代金前払い']},
    {"surface": "後日送金", "reading": "ごじつそうきん", "vi_short": "thanh toán chuyển tiền sau khi nhận hàng (Deferred T/T)", "vi_explanation": "Bên mua nhận hàng kiểm tra xong xuôi mới chuyển tiền trả cho bên bán sau một khoảng thời gian thỏa thuận (30 hoặc 60 ngày).", "en_preferred": "Deferred payment / Open Account (O/A)", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['O/A'], "antonyms": ['前受送金'], "related_terms": ['掛売り', '決済']},
    {"surface": "D/P", "reading": "でぃーぴー", "vi_short": "nhờ thu trả tiền lấy chứng từ (Documents Against Payment)", "vi_explanation": "Phương thức người mua phải chuyển tiền trả ngay cho ngân hàng thì ngân hàng mới giao bộ chứng từ vận tải gốc B/L để đi nhận hàng.", "en_preferred": "Documents Against Payment (D/P)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['支払渡し'], "antonyms": [], "related_terms": ['D/A', '荷為替']},
    {"surface": "D/A", "reading": "でぃーえー", "vi_short": "nhờ thu chấp nhận thanh toán lấy chứng từ (Documents Against Acceptance)", "vi_explanation": "Người mua chỉ cần ký vào hối phiếu cam kết trả tiền vào một ngày trong tương lai là được ngân hàng giao ngay chứng từ để lấy hàng trước.", "en_preferred": "Documents Against Acceptance (D/A)", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['引受渡し'], "antonyms": [], "related_terms": ['D/P', '為替手形']},
    {"surface": "手形引受", "reading": "てがたひきうけ", "vi_short": "chấp nhận thanh toán hối phiếu kỳ hạn", "vi_explanation": "Hành vi người mua ký tên xác nhận vào mặt trước của hối phiếu cam kết sẽ thanh toán đầy đủ số tiền khi đến ngày đáo hạn ghi trên hối phiếu.", "en_preferred": "Acceptance of bill of exchange", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['D/A', '満期日']},
    {"surface": "外国為替", "reading": "がいこくかわせ", "vi_short": "thị trường ngoại hối / ngoại tệ", "vi_explanation": "Hệ thống chuyển đổi thanh toán giữa các đồng tiền của các quốc gia khác nhau thông qua các tổ chức tài chính.", "en_preferred": "Foreign exchange (Forex / FX)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['為替', 'FX'], "antonyms": [], "related_terms": ['為替レート', '外貨']},
    {"surface": "為替レート", "reading": "かわせれーと", "vi_short": "tỷ giá hối đoái", "vi_explanation": "Mức giá quy đổi giá trị giữa đồng tiền của hai quốc gia (ví dụ tỷ giá giữa đồng Yên Nhật JPY và Đô la Mỹ USD).", "en_preferred": "Exchange rate", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['為替相場'], "antonyms": [], "related_terms": ['円高', '円安', 'TTM']},
    {"surface": "円高", "reading": "えんだか", "vi_short": "đồng Yên tăng giá so với ngoại tệ", "vi_explanation": "Hiện tượng giá trị đồng Yên tăng lên so với đồng USD, mang lại lợi thế lớn cho các doanh nghiệp nhập khẩu nhưng gây bất lợi cho doanh nghiệp xuất khẩu.", "en_preferred": "Strong Yen / Yen appreciation", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": ['円安'], "related_terms": ['為替差益', '輸入有利']},
    {"surface": "円安", "reading": "えんやす", "vi_short": "đồng Yên giảm giá so với ngoại tệ", "vi_explanation": "Hiện tượng giá trị đồng Yên sụt giảm, giúp hàng hóa xuất khẩu của Nhật Bản trở nên rẻ và cạnh tranh hơn trên thị trường quốc tế.", "en_preferred": "Weak Yen / Yen depreciation", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": ['円高'], "related_terms": ['為替差損', '輸出有利']},
    {"surface": "為替予約", "reading": "かわせよやく", "vi_short": "hợp đồng kỳ hạn phòng ngừa rủi ro tỷ giá", "vi_explanation": "Hợp đồng ký kết với ngân hàng ấn định trước mức tỷ giá hối đoái cho một giao dịch chuyển đổi tiền trong tương lai nhằm khóa rủi ro biến động.", "en_preferred": "Forward exchange contract / FX forward", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['先物為替予約'], "antonyms": [], "related_terms": ['為替リスク', 'ヘッジ']},
    {"surface": "スポットレート", "reading": "すぽっとれーと", "vi_short": "tỷ giá giao ngay", "vi_explanation": "Mức tỷ giá hối đoái áp dụng cho các giao dịch chuyển đổi ngoại tệ được thực hiện và thanh toán bù trừ trong vòng 2 ngày làm việc.", "en_preferred": "Spot rate", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": ['フォワードレート'], "related_terms": ['外国為替']},
    {"surface": "フォワードレート", "reading": "ふぉわーどれーと", "vi_short": "tỷ giá kỳ hạn trong tương lai", "vi_explanation": "Mức tỷ giá được thỏa thuận cố định hôm nay để áp dụng cho việc giao nhận ngoại tệ vào một ngày cụ thể trong tương lai.", "en_preferred": "Forward rate", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": ['スポットレート'], "related_terms": ['為替予約']},
    {"surface": "TTB", "reading": "てぃーてぃーびー", "vi_short": "tỷ giá ngân hàng mua vào ngoại tệ (Telegraphic Transfer Buying rate)", "vi_explanation": "Mức tỷ giá ngân hàng áp dụng để mua lại ngoại tệ từ tài khoản của khách hàng để quy đổi sang tiền Yên.", "en_preferred": "Telegraphic Transfer Buying rate (TTB)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['対顧客電信買相場'], "antonyms": [], "related_terms": ['TTS', 'TTM']},
    {"surface": "TTS", "reading": "てぃーてぃーえす", "vi_short": "tỷ giá ngân hàng bán ra ngoại tệ (Telegraphic Transfer Selling rate)", "vi_explanation": "Mức tỷ giá ngân hàng áp dụng để bán ngoại tệ cho khách hàng có nhu cầu chuyển tiền thanh toán tiền hàng ra nước ngoài.", "en_preferred": "Telegraphic Transfer Selling rate (TTS)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['対顧客電信売相場'], "antonyms": [], "related_terms": ['TTB', 'TTM']},
    {"surface": "TTM", "reading": "てぃーてぃーえむ", "vi_short": "tỷ giá trung bình chuẩn hàng ngày của ngân hàng", "vi_explanation": "Mức tỷ giá trung bình giữa giá mua và giá bán được ngân hàng công bố vào lúc 10h sáng hàng ngày làm mốc cơ sở tính toán thuế và sổ sách kế toán.", "en_preferred": "Telegraphic Transfer Middle rate (TTM)", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:finance", "synonyms": ['仲値'], "antonyms": [], "related_terms": ['TTB', 'TTS', '為替換算']},
    {"surface": "コルレス銀行", "reading": "こるれすぎんこう", "vi_short": "ngân hàng đại lý thanh toán quốc tế (Correspondent Bank)", "vi_explanation": "Ngân hàng nước ngoài có ký kết thỏa thuận đại lý với ngân hàng trong nước để mở tài khoản hỗ trợ thanh toán bù trừ các lệnh chuyển tiền qua biên giới.", "en_preferred": "Correspondent bank", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['SWIFT', '送金ルート']},
    {"surface": "為替リスク", "reading": "かわせりすく", "vi_short": "rủi ro biến động tỷ giá hối đoái", "vi_explanation": "Nguy cơ doanh nghiệp bị thua lỗ tài chính khi quy đổi ngoại tệ do tỷ giá đồng tiền biến động bất lợi giữa thời điểm ký hợp đồng và lúc thanh toán.", "en_preferred": "Foreign exchange risk / Currency risk", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['為替予約', 'ヘッジ']},
    {"surface": "外貨預金", "reading": "がいかよきん", "vi_short": "tài khoản tiền gửi bằng đồng ngoại tệ", "vi_explanation": "Tài khoản ngân hàng mở tại Nhật Bản nhưng lưu giữ bằng các đồng ngoại tệ mạnh như USD hoặc EUR để phục vụ thanh toán xuất nhập khẩu.", "en_preferred": "Foreign currency deposit", "tier": "PRO-A1", "priority": 96, "source_reference": "jetro_trade_corpus:finance", "synonyms": [], "antonyms": [], "related_terms": ['為替手数料', '普通預金']},
    {"surface": "フォワーダー", "reading": "ふぉわーだー", "vi_short": "công ty giao nhận vận tải quốc tế (Freight Forwarder)", "vi_explanation": "Đơn vị cung cấp giải pháp vận tải đa phương thức trọn gói, đứng ra thu xếp thủ tục hải quan, đặt chỗ tàu và xe tải chở hàng tận nơi cho khách.", "en_preferred": "Freight Forwarder", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['利用運送事業者'], "antonyms": [], "related_terms": ['乙仲', '船社', '複合一貫輸送']},
    {"surface": "乙仲", "reading": "おつなか", "vi_short": "đại lý giao nhận hải quan và vận tải truyền thống tại cảng", "vi_explanation": "Tên gọi truyền thống của các công ty làm dịch vụ thông quan hải quan và thủ tục xếp dỡ hàng hóa tại các thương cảng Nhật Bản.", "en_preferred": "Customs broker / Forwarding agent (traditional term)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['海運貨物取扱業者'], "antonyms": [], "related_terms": ['フォワーダー', '通関業者']},
    {"surface": "船社", "reading": "せんしゃ", "vi_short": "hãng tàu biển vận tải hàng hóa quốc tế", "vi_explanation": "Doanh nghiệp trực tiếp sở hữu hoặc thuê vận hành đội tàu biển chuyên chở container hoặc hàng rời giữa các cảng biển trên thế giới.", "en_preferred": "Shipping line / Ocean carrier", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['海運会社'], "antonyms": [], "related_terms": ['船荷証券', 'ブッキング']},
    {"surface": "航空会社", "reading": "こうくうがいしゃ", "vi_short": "hãng hàng không chuyên chở hàng hóa", "vi_explanation": "Doanh nghiệp khai thác các chuyến bay chuyên dụng chở hàng hóa hoặc vận chuyển hàng trong khoang bụng của máy bay chở khách.", "en_preferred": "Airline / Air cargo carrier", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": [], "related_terms": ['航空貨物運送状', 'フォワーダー']},
    {"surface": "コンテナ船", "reading": "こんてなせん", "vi_short": "tàu chở container chuyên dụng", "vi_explanation": "Loại tàu biển hiện đại có cấu trúc được thiết kế đặc thù để xếp chồng hàng ngàn thùng container tiêu chuẩn 20 feet và 40 feet.", "en_preferred": "Container ship / Container vessel", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['在来船'], "related_terms": ['TEU', 'コンテナヤード']},
    {"surface": "在来船", "reading": "ざいらいせん", "vi_short": "tàu chở hàng bách hóa tổng hợp truyền thống", "vi_explanation": "Tàu biển chở các loại hàng hóa cồng kềnh, thiết bị máy móc nặng hoặc hàng bao kiện không thể đóng vừa bên trong thùng container.", "en_preferred": "Conventional cargo ship / Breakbulk vessel", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['コンテナ船'], "related_terms": ['バルク船', '荷役']},
    {"surface": "バルク船", "reading": "ばるくせん", "vi_short": "tàu chở hàng rời không đóng gói", "vi_explanation": "Tàu chuyên dụng để chở các loại nguyên liệu thô với khối lượng khổng lồ đổ trực tiếp vào hầm tàu như than đá, quặng sắt, lúa mì hoặc dầu thô.", "en_preferred": "Bulk carrier / Bulk vessel", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['ばら積み船'], "antonyms": [], "related_terms": ['在来船', '鉱石船']},
    {"surface": "FCL貨物", "reading": "えふしーえるかもつ", "vi_short": "hàng nguyên một container (Full Container Load)", "vi_explanation": "Lô hàng của một chủ hàng duy nhất có số lượng đủ lớn để đóng đầy trọn vẹn một hoặc nhiều thùng container.", "en_preferred": "Full Container Load (FCL)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['フルコンテナ'], "antonyms": ['LCL貨物'], "related_terms": ['コンテナヤード', 'バンニング']},
    {"surface": "LCL貨物", "reading": "えるしーえるかもつ", "vi_short": "hàng lẻ đóng ghép chung container (Less than Container Load)", "vi_explanation": "Lô hàng nhỏ lẻ không đủ đóng riêng một container, phải gom chung vào kho CFS để đóng ghép container với các chủ hàng khác.", "en_preferred": "Less than Container Load (LCL)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['混載貨物'], "antonyms": ['FCL貨物'], "related_terms": ['コンテナフレイトステーション', '混載業者']},
    {"surface": "バンニング", "reading": "ばんにんぐ", "vi_short": "đóng hàng vào bên trong thùng container (Vanning)", "vi_explanation": "Thao tác xếp dỡ, chèn lót và cố định chắc chắn hàng hóa vào bên trong vỏ container trước khi khóa seal cửa.", "en_preferred": "Vanning / Container stuffing", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['詰め込み'], "antonyms": ['デバンニング'], "related_terms": ['ラッシング', 'CLP']},
    {"surface": "デバンニング", "reading": "でばんにんぐ", "vi_short": "dỡ hàng ra khỏi thùng container (Devanning)", "vi_explanation": "Thao tác mở kẹp chì niêm phong seal và bốc dỡ toàn bộ hàng hóa ra khỏi vỏ container tại kho đích.", "en_preferred": "Devanning / Container stripping", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['荷卸し'], "antonyms": ['バンニング'], "related_terms": ['コンテナヤード', '検数']},
    {"surface": "コンテナヤード", "reading": "こんてなやーど", "vi_short": "bãi bốc dỡ và lưu giữ container tại cảng (CY)", "vi_explanation": "Khu vực bãi ngoài trời tại thương cảng chuyên dùng để hạ bãi, tiếp nhận và chuyển giao các thùng container nguyên FCL.", "en_preferred": "Container Yard (CY)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['CY'], "antonyms": [], "related_terms": ['CFS', 'ガントリークレーン']},
    {"surface": "コンテナフレイトステーション", "reading": "こんてなふれいとすてーしょん", "vi_short": "kho gom và chia hàng lẻ tại cảng (CFS)", "vi_explanation": "Khu nhà kho tại cảng chuyên trách việc tiếp nhận hàng lẻ LCL, thực hiện đóng ghép chung vào container hoặc dỡ hàng chia nhỏ cho từng chủ hàng.", "en_preferred": "Container Freight Station (CFS)", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['CFS'], "antonyms": [], "related_terms": ['CY', 'LCL貨物']},
    {"surface": "リーファーコンテナ", "reading": "りーふぁーこんてな", "vi_short": "container bảo ôn có máy làm lạnh (Reefer Container)", "vi_explanation": "Vỏ container chuyên dụng có trang bị máy nén lạnh để điều chỉnh và duy trì nhiệt độ ổn định bảo quản thực phẩm đông lạnh hoặc thuốc y tế.", "en_preferred": "Reefer container / Refrigerated container", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['ドライコンテナ'], "related_terms": ['温度管理', '定温輸送']},
    {"surface": "ドライコンテナ", "reading": "どらいこんてな", "vi_short": "container chở hàng khô tiêu chuẩn thông thường", "vi_explanation": "Loại vỏ container phổ biến nhất chiếm 90% lượng hàng vận tải biển, dùng chở các mặt hàng khô không yêu cầu nhiệt độ bảo quản.", "en_preferred": "Dry container / Standard container", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['リーファーコンテナ'], "related_terms": ['TEU', '20フィート']},
    {"surface": "デマレージ", "reading": "でまれーじ", "vi_short": "phí phạt lưu bãi container quá hạn tại cảng", "vi_explanation": "Khoản tiền phạt bên nhận hàng phải nộp cho hãng tàu nếu để container quá thời gian miễn phí cho phép mà chưa đến nhận mang về.", "en_preferred": "Demurrage", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['ディテンション'], "related_terms": ['フリータイム', 'コンテナヤード']},
    {"surface": "ディテンション", "reading": "でぃてんしょん", "vi_short": "phí phạt lưu vỏ container quá hạn trả về bãi", "vi_explanation": "Khoản tiền phạt phải trả cho hãng tàu nếu bên nhận hàng giữ vỏ container tại kho riêng quá lâu mà không đem trả vỏ rỗng về bãi cảng.", "en_preferred": "Detention charge", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['デマレージ'], "related_terms": ['フリータイム', '空コンテナ']},
    {"surface": "フリータイム", "reading": "ふりーたいむ", "vi_short": "thời gian miễn phí lưu bãi và lưu vỏ container", "vi_explanation": "Khoảng thời gian (thường từ 7 đến 14 ngày) hãng tàu cho phép chủ hàng lưu container tại cảng hoặc giữ vỏ container mà không bị tính phí phạt.", "en_preferred": "Free time", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": [], "related_terms": ['デマレージ', 'ディテンション']},
    {"surface": "海上運賃", "reading": "かいじょううんちん", "vi_short": "cước vận tải đường biển", "vi_explanation": "Khoản chi phí thanh toán cho hãng tàu biển để vận chuyển container hoặc hàng hóa bằng đường biển giữa cảng đi và cảng đến.", "en_preferred": "Ocean freight / Sea freight", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['オーシャンフレイト'], "antonyms": [], "related_terms": ['航空運賃', '運賃明細']},
    {"surface": "航空運賃", "reading": "こうくううんちん", "vi_short": "cước vận tải hàng không", "vi_explanation": "Chi phí trả cho hãng hàng không để vận chuyển các bưu kiện hoặc hàng hóa hỏa tốc bằng máy bay, tính dựa trên trọng lượng hoặc thể tích.", "en_preferred": "Air freight", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": ['海上運賃'], "related_terms": ['容積重量', '実重量']},
    {"surface": "燃料サーチャージ", "reading": "ねんりょうさーちゃーじ", "vi_short": "phụ phí nhiên liệu biến động (BAF / FSC)", "vi_explanation": "Khoản phụ phí cước thu bổ sung nhằm bù đắp biến động giá dầu thô trên thị trường thế giới đối với vận tải biển và hàng không.", "en_preferred": "Bunker Adjustment Factor (BAF) / Fuel surcharge", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['BAF', '燃油サーチャージ'], "antonyms": [], "related_terms": ['海上運賃', 'サーチャージ']},
    {"surface": "通貨変動サーチャージ", "reading": "つうかへんどうさーちゃーじ", "vi_short": "phụ phí biến động tỷ giá tiền tệ (CAF)", "vi_explanation": "Phụ phí hãng tàu thu thêm để bù đắp rủi ro mất giá của đồng tiền định giá cước vận tải so với đồng tiền thanh toán thực tế.", "en_preferred": "Currency Adjustment Factor (CAF)", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['CAF'], "antonyms": [], "related_terms": ['為替変動', '海上運賃']},
    {"surface": "ターミナルハンドリングチャージ", "reading": "たーみなるはんどりんぐちゃーじ", "vi_short": "phí nâng hạ và bốc dỡ tại bến cảng (THC)", "vi_explanation": "Khoản phí bến bãi mà người gửi hàng hoặc nhận hàng phải nộp cho cảng để chi trả việc cẩu container từ bãi lên tàu và ngược lại.", "en_preferred": "Terminal Handling Charge (THC)", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['THC'], "antonyms": [], "related_terms": ['海上運賃', '港湾費用']},
    {"surface": "船積み", "reading": "ふなづみ", "vi_short": "bốc hàng lên tàu vận tải biển", "vi_explanation": "Thao tác cẩu hàng hóa từ cầu cảng đặt an toàn vào các hầm hàng hoặc trên boong tàu thủy.", "en_preferred": "Loading / Shipment on board", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['積載'], "antonyms": ['陸揚げ'], "related_terms": ['船積日', '船荷証券']},
