    {"surface": "共同海損", "reading": "きょうどうかいそん", "vi_short": "tổn thất chung trong hàng hải (General Average - GA)", "vi_explanation": "Quy tắc hàng hải cổ xưa: khi gặp nguy hiểm trên biển (cháy tàu, mắc cạn), thuyền trưởng chủ động hy sinh vứt một số hàng xuống biển để cứu tàu thì mọi chủ hàng cùng chia sẻ tổn thất.", "en_preferred": "General Average (GA)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['GA'], "antonyms": ['単独海損'], "related_terms": ['海上保険', 'ヨーク・アントワープ規則']},
    {"surface": "単独海損", "reading": "たんどくかいそん", "vi_short": "tổn thất riêng của từng chủ hàng (Particular Average - PA)", "vi_explanation": "Thiệt hại xảy ra chỉ đối với lô hàng của riêng một chủ hàng do nguyên nhân ngẫu nhiên như va đập hoặc nước biển tràn vào, bên đó tự chịu trách nhiệm.", "en_preferred": "Particular Average (PA)", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['PA'], "antonyms": ['共同海損'], "related_terms": ['分損担保', '海上保険']},
