    {"surface": "分損担保", "reading": "ぶんそんたんぽ", "vi_short": "bảo hiểm có bồi thường tổn thất bộ phận (With Average - WA)", "vi_explanation": "Điều kiện bảo hiểm chi trả bồi thường cho cả trường hợp hàng hóa bị hư hỏng một phần (tổn thất riêng) do thiên tai biển cả gây ra.", "en_preferred": "With Average (WA) / Institute Cargo Clauses (B)", "tier": "PRO-A2", "priority": 91, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['WA'], "antonyms": ['分損不担保'], "related_terms": ['全危険担保']},
    {"surface": "分損不担保", "reading": "ぶんそんふたんぽ", "vi_short": "bảo hiểm miễn bồi thường tổn thất riêng bộ phận (Free of Particular Average - FPA)", "vi_explanation": "Điều kiện bảo hiểm cơ bản nhất chỉ bồi thường khi tàu bị đắm, cháy, mắc cạn hoặc toàn bộ lô hàng bị mất trắng.", "en_preferred": "Free of Particular Average (FPA) / Institute Cargo Clauses (C)", "tier": "PRO-A2", "priority": 90, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['FPA'], "antonyms": ['分損担保'], "related_terms": ['全損']},
    {"surface": "荷崩れ", "reading": "にくずれ", "vi_short": "đổ sụp xô lệch hàng hóa trong thùng container", "vi_explanation": "Sự cố hàng hóa bị nghiêng ngả, rơi đổ hoặc dập nát bên trong vỏ container do tàu biển chao đảo mạnh hoặc chèn lót không kỹ.", "en_preferred": "Collapse of cargo / Cargo shifting", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:logistics", "synonyms": [], "antonyms": [], "related_terms": ['ラッシング', '事故報告書']},
