    {"surface": "容積重量", "reading": "ようせきじゅうりょう", "vi_short": "trọng lượng quy đổi theo thể tích (Volumetric Weight)", "vi_explanation": "Trọng lượng tính cước vận tải bằng cách lấy chiều dài x rộng x cao (cm) chia cho 5000 hoặc 6000 đối với các kiện hàng nhẹ nhưng cồng kềnh.", "en_preferred": "Volumetric weight / Dimensional weight", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:logistics", "synonyms": ['ボリュームウェイト'], "antonyms": ['実重量'], "related_terms": ['航空運賃', '運賃計算']},
    {"surface": "自由貿易協定", "reading": "じゆうぼうえききょうてい", "vi_short": "hiệp định thương mại tự do (FTA)", "vi_explanation": "Hiệp ước giữa hai hay nhiều quốc gia nhằm xóa bỏ hàng rào thuế quan và hạn ngạch thương mại để hàng hóa lưu thông tự do.", "en_preferred": "Free Trade Agreement (FTA)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['FTA'], "antonyms": [], "related_terms": ['経済連携協定', '原産地規則']},
    {"surface": "経済連携協定", "reading": "けいざいれんけいきょうてい", "vi_short": "hiệp định đối tác kinh tế toàn diện (EPA)", "vi_explanation": "Hiệp ước hợp tác sâu rộng hơn FTA, bao gồm cả xóa bỏ thuế quan, bảo hộ sở hữu trí tuệ, dịch vụ tài chính và di chuyển lao động.", "en_preferred": "Economic Partnership Agreement (EPA)", "tier": "PRO-A1", "priority": 100, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['EPA'], "antonyms": [], "related_terms": ['FTA', '特定原産地証明書']},
    {"surface": "環太平洋パートナーシップ協定", "reading": "かんたいへいようぱーとなーしっぷきょうてい", "vi_short": "Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP / TPP11)", "vi_explanation": "Hiệp định thương mại tự do thế hệ mới tiêu chuẩn cao gồm 11 quốc gia khu vực châu Á - Thái Bình Dương (trong đó có Nhật Bản và Việt Nam).", "en_preferred": "Comprehensive and Progressive Agreement for Trans-Pacific Partnership (CPTPP)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['CPTPP', 'TPP11'], "antonyms": [], "related_terms": ['RCEP', 'EPA']},
    {"surface": "地域的な包括的経済連携協定", "reading": "ちいきてきなほうかつてきけいざいれんけいきょうてい", "vi_short": "Hiệp định Đối tác Kinh tế Toàn diện Khu vực (RCEP)", "vi_explanation": "Khối thương mại tự do lớn nhất thế giới gồm 15 quốc gia thành viên (10 nước ASEAN cùng Nhật Bản, Trung Quốc, Hàn Quốc, Úc, New Zealand).", "en_preferred": "Regional Comprehensive Economic Partnership (RCEP)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['RCEP'], "antonyms": [], "related_terms": ['CPTPP', '日中貿易']},
