    {"surface": "原産地規則", "reading": "げんさんちきそく", "vi_short": "quy tắc xuất xứ hàng hóa (Rules of Origin)", "vi_explanation": "Bộ tiêu chí kỹ thuật quy định điều kiện để một sản phẩm được công nhận là có xuất xứ từ một quốc gia thành viên để hưởng thuế ưu đãi.", "en_preferred": "Rules of Origin (ROO)", "tier": "PRO-A1", "priority": 98, "source_reference": "jetro_trade_corpus:agreements", "synonyms": [], "antonyms": [], "related_terms": ['完全生産品', '実質的変更基準']},
    {"surface": "完全生産品", "reading": "かんぜんせいさんひん", "vi_short": "hàng hóa được sản xuất thuần túy 100% tại một quốc gia (Wholly Obtained)", "vi_explanation": "Nông sản thu hoạch, khoáng sản khai thác hoặc gia súc nuôi sinh ra hoàn toàn 100% trong phạm vi lãnh thổ của một quốc gia.", "en_preferred": "Wholly Obtained Goods (WO)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['WO'], "antonyms": [], "related_terms": ['原産地規則', '実質的変更基準']},
    {"surface": "原産資格割合", "reading": "げんさんしかくわりあい", "vi_short": "hàm lượng giá trị khu vực đạt tiêu chuẩn (Regional Value Content - RVC)", "vi_explanation": "Tỷ lệ phần trăm giá trị gia tăng được tạo ra tại các nước thành viên trong hiệp định trên tổng trị giá sản phẩm (thường phải đạt trên 40%).", "en_preferred": "Regional Value Content (RVC)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['RVC', '付加価値基準'], "antonyms": [], "related_terms": ['原産地規則', '計算式']},
    {"surface": "関税分類変更基準", "reading": "かんぜいぶんるいへんこうきじゅん", "vi_short": "tiêu chí chuyển đổi mã số thuế quan (Change in Tariff Classification - CTC)", "vi_explanation": "Quy tắc xác định xuất xứ: nguyên liệu nhập khẩu phải trải qua quá trình chế biến sâu làm thay đổi mã số HS ở cấp 2, 4 hoặc 6 chữ số.", "en_preferred": "Change in Tariff Classification (CTC)", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['CTC'], "antonyms": [], "related_terms": ['HSコード', '実質的変更基準']},
    {"surface": "付加価値基準", "reading": "ふかかちきじゅん", "vi_short": "tiêu chí tỷ lệ giá trị gia tăng nội địa", "vi_explanation": "Quy tắc công nhận xuất xứ nếu phần giá trị gia tăng tạo ra trong nước đạt một tỷ lệ nhất định so với giá bán xuất xưởng của sản phẩm.", "en_preferred": "Value Added Rule (VA rule)", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:agreements", "synonyms": [], "antonyms": [], "related_terms": ['RVC', '原産地規則']},
    {"surface": "自己申告制度", "reading": "じこしんこくせいど", "vi_short": "chế độ tự chứng nhận xuất xứ của nhà xuất khẩu", "vi_explanation": "Cơ chế theo hiệp định EPA hiện đại cho phép doanh nghiệp tự phát hành văn bản khai báo xuất xứ trên hóa đơn mà không cần xin cấp chứng nhận C/O từ Phòng Thương mại.", "en_preferred": "Self-certification system of origin", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:agreements", "synonyms": ['自己証明'], "antonyms": ['第三者証明制度'], "related_terms": ['日欧EPA', 'インボイス申告']},
    {"surface": "第三者証明制度", "reading": "だいさんしゃしょうめいせいど", "vi_short": "chế độ chứng nhận xuất xứ qua bên thứ ba (Phòng Thương mại)", "vi_explanation": "Quy trình truyền thống doanh nghiệp phải nộp tài liệu giải trình cho Phòng Thương mại Công nghiệp (JCCI) để được cấp phôi C/O giấy.", "en_preferred": "Third-party certification system", "tier": "PRO-A2", "priority": 92, "source_reference": "jetro_trade_corpus:agreements", "synonyms": [], "antonyms": ['自己申告制度'], "related_terms": ['日本商工会議所', '特定原産地証明書']},
    {"surface": "安全保障貿易管理", "reading": "あんぜんほしょうぼうえきかんり", "vi_short": "quản lý ngoại thương phục vụ an ninh quốc gia", "vi_explanation": "Chính sách kiểm soát chặt chẽ của Bộ Kinh tế Thương mại và Công nghiệp (METI) nhằm ngăn chặn vũ khí và hàng hóa công nghệ cao rơi vào tay khủng bố.", "en_preferred": "Security export control", "tier": "PRO-A1", "priority": 97, "source_reference": "jetro_trade_corpus:regulations", "synonyms": [], "antonyms": [], "related_terms": ['外為法', 'リスト規制', '経済産業省']},
    {"surface": "外国為替及び外国貿易法", "reading": "がいこくかわせおよびがいこくぼうえきほう", "vi_short": "Luật Ngoại hối và Ngoại thương Nhật Bản (Gaitameho)", "vi_explanation": "Đạo luật nền tảng kiểm soát mọi luồng giao dịch tiền tệ, thanh toán quốc tế và xuất nhập khẩu hàng hóa xuyên biên giới của Nhật Bản.", "en_preferred": "Foreign Exchange and Foreign Trade Act (FEFTA)", "tier": "PRO-A1", "priority": 99, "source_reference": "jetro_trade_corpus:regulations", "synonyms": ['外為法'], "antonyms": [], "related_terms": ['安全保障貿易管理', '輸出令']},
    {"surface": "リスト規制", "reading": "りすときせい", "vi_short": "kiểm soát xuất khẩu theo danh mục công nghệ vũ khí cấm", "vi_explanation": "Quy định bắt buộc phải xin giấy phép của Bộ METI khi xuất khẩu các mặt hàng nằm trong danh mục kỹ thuật có khả năng chế tạo vũ khí hạt nhân hoặc tên lửa.", "en_preferred": "List control regulations", "tier": "PRO-A2", "priority": 94, "source_reference": "jetro_trade_corpus:regulations", "synonyms": [], "antonyms": ['キャッチオール規制'], "related_terms": ['外為法', '該非判定']},
    {"surface": "キャッチオール規制", "reading": "きゃっちおーるきせい", "vi_short": "quy định kiểm soát xuất khẩu bao trùm mọi mặt hàng", "vi_explanation": "Quy định cho phép chặn xuất khẩu bất kỳ mặt hàng công nghiệp dân dụng bình thường nào nếu có nguy cơ bị phía mua sử dụng cho mục đích quân sự.", "en_preferred": "Catch-all control regulations", "tier": "PRO-A2", "priority": 93, "source_reference": "jetro_trade_corpus:regulations", "synonyms": [], "antonyms": ['リスト規制'], "related_terms": ['エンドユーザー', '用途確認']},
    {"surface": "該非判定", "reading": "がいひはんてい", "vi_short": "thẩm định đánh giá tính chất nhạy cảm của hàng hóa công nghệ", "vi_explanation": "Quy trình kỹ thuật nội bộ của công ty so sánh các thông số kỹ thuật của sản phẩm với danh mục cấm của Bộ METI để xem có thuộc diện phải xin phép hay không.", "en_preferred": "Classification / Applicability determination", "tier": "PRO-A2", "priority": 95, "source_reference": "jetro_trade_corpus:regulations", "synonyms": [], "antonyms": [], "related_terms": ['該非判定書', 'リスト規制']},
